DOMAINS = {'allocation': (0.0, 1.0), 'lookback': (2.0, 10.0), 'hold': (1.0, 30.0), 'confirmation': (1.0, 5.0)}
def coordinate_names(parameters):
    if parameters["mode"] != "center_below" or parameters["center_kind"] != "mean":
